using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.InputSystem;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class OnLookInspect {
 public static object Run(){var s=SceneManager.GetActiveScene();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)).Where(c=>c).ToArray();var result=new{scene=s.path,s.isDirty,playing=Application.isPlaying,frame=Time.frameCount,focused=Application.isFocused,focusedWindow=EditorWindow.focusedWindow?EditorWindow.focusedWindow.GetType().Name:null,cursor=Cursor.lockState.ToString(),devices=InputSystem.devices.Select(d=>new{d.name,d.enabled,d.added,d.deviceId,d.native,description=d.description.ToString()}).ToArray(),background=InputSystem.settings.backgroundBehavior.ToString(),editorBehavior=InputSystem.settings.editorInputBehaviorInPlayMode.ToString(),inputs=all.OfType<PlayerInput>().Select(pi=>new{pi.name,pi.enabled,pi.inputIsActive,pi.currentControlScheme,map=pi.currentActionMap?.name,defaultMap=pi.defaultActionMap,behavior=pi.notificationBehavior.ToString(),asset=AssetDatabase.GetAssetPath(pi.actions),devices=pi.devices.Select(d=>new{d.name,d.enabled,d.deviceId}).ToArray(),events=pi.actionEvents.Select(e=>new{e.actionId,e.actionName,listeners=Enumerable.Range(0,e.GetPersistentEventCount()).Select(i=>new{method=e.GetPersistentMethodName(i),target=e.GetPersistentTarget(i)?e.GetPersistentTarget(i).name:null,state=e.GetPersistentListenerState(i).ToString()}).ToArray()}).ToArray(),actions=pi.actions?.Select(a=>new{a.name,a.enabled,phase=a.phase.ToString(),bindings=a.bindings.Select(b=>new{b.path,b.effectivePath,b.groups,b.interactions,b.processors}).ToArray(),controls=a.controls.Select(c=>c.path).ToArray()}).ToArray()}).ToArray(),components=all.Where(c=>c.GetType().Name=="PlayerLook"||c.GetType().Name=="PlayerPresenter"||c.GetType().Name.StartsWith("CinemachineVirtualCamera")).Select(c=>new{name=c.gameObject.name,type=c.GetType().Name,c.enabled,active=c.gameObject.activeInHierarchy,json=EditorJsonUtility.ToJson(c)}).ToArray(),cameras=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).Select(c=>new{c.name,c.enabled,active=c.gameObject.activeInHierarchy,rotation=c.transform.eulerAngles.ToString()}).ToArray()};string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/Diagnostics/OnLook_20261109/"));File.WriteAllText(h+(Application.isPlaying?"play":"edit")+"_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
